        int n = haystack.length(), m = needle.length();
        if (m == 0) return 0;
        long base = 256, mod = 1_000_000_007L;
        long highPower = 1;
        for (int i = 0; i < m - 1; i++) highPower = (highPower * base) % mod;

        long needleHash = 0, windowHash = 0;
        for (int i = 0; i < m; i++) {
            needleHash = (needleHash * base + needle.charAt(i)) % mod;
            windowHash = (windowHash * base + haystack.charAt(i)) % mod;
        }

        for (int i = 0; i <= n - m; i++) {
            if (windowHash == needleHash && haystack.substring(i, i + m).equals(needle)) { // verify against a collision
                return i;
            }
            if (i + m < n) {
                windowHash = (windowHash - haystack.charAt(i) * highPower % mod + mod) % mod;
                windowHash = (windowHash * base + haystack.charAt(i + m)) % mod;              // roll the window forward
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        String haystack = "sadbutsad";
        String needle = "sad";
        Main solution = new Main();
        System.out.println(solution.strStr(haystack, needle));
    }
}

