#include <bits/stdc++.h>
using namespace std;

int strStr(string haystack, string needle) {
    int n = (int)haystack.size(), m = (int)needle.size();
    if (m == 0) return 0;
    long long base = 256, mod = 1000000007;
    long long highPower = 1;
    for (int i = 0; i < m - 1; i++) highPower = (highPower * base) % mod;

    long long needleHash = 0, windowHash = 0;
    for (int i = 0; i < m; i++) {
        needleHash = (needleHash * base + (unsigned char)needle[i]) % mod;
        windowHash = (windowHash * base + (unsigned char)haystack[i]) % mod;
    }

    for (int i = 0; i <= n - m; i++) {
        if (windowHash == needleHash && haystack.substr(i, m) == needle) {   // verify against a hash collision
            return i;
        }
        if (i + m < n) {
            windowHash = (windowHash - (unsigned char)haystack[i] * highPower % mod + mod) % mod;
            windowHash = (windowHash * base + (unsigned char)haystack[i + m]) % mod;         // roll forward
        }
    }
    return -1;
}

int main() {
    string haystack = "sadbutsad";
    string needle = "sad";
    cout << strStr(haystack, needle) << endl;
    return 0;
}
